params.command:
$ports=22,445,5985,5986
$rows=@()
foreach($p in $ports){
  $ok=$false
  try { $ok=(Test-NetConnection -ComputerName heaven2 -Port $p -InformationLevel Quiet -WarningAction SilentlyContinue) } catch {}
  $rows += [pscustomobject]@{port=$p;open=[bool]$ok}
}
$th=$null
try {$th=(Get-Item WSMan:\localhost\Client\TrustedHosts -ErrorAction Stop).Value} catch {}
[pscustomobject]@{trusted_hosts=$th;ports=$rows}|ConvertTo-Json -Compress -Depth 4
